import{_ as i,l as o,o as e,c as n,v as l,p,x as t,d as s,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"Campbell–Shiller 分解","description":"","frontmatter":{"title":"Campbell–Shiller 分解","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/campbell-shiller-decomposition.md","filePath":"econ/campbell-shiller-decomposition.md","lastUpdated":1789023840000}'),m={name:"econ/campbell-shiller-decomposition.md"};function h(_,a,u,b,E,S){const r=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=l('<h1 id="campbell–shiller-分解" tabindex="-1">Campbell–Shiller 分解 <a class="header-anchor" href="#campbell–shiller-分解" aria-label="Permalink to &quot;Campbell–Shiller 分解&quot;">​</a></h1><div class="epigraph"><p>股利–价格比高，不是因为预期股利要涨，就是因为预期回报要高，或者泡沫项在爆炸；对数线性把它收成会计。</p><footer>—— Campbell and Shiller, The Dividend-Price Ratio and Expectations of Future Dividends and Discount Factors, Review of Financial Studies, 1988</footer></div><p><a href="/econ/lucas-tree">上一课</a>给出 \\(p=p(y)\\) 的均衡函数。本课缺口是<strong>不指定 \\(u\\)</strong>：从回报的定义出发，对数线性化后，价格相对股利的位置必须被未来股利增长或未来回报（或泡沫）解释。这是会计，不是又一个欧拉。不重解 Bellman。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>净回报 \\(1+R_{t+1}=(P_{t+1}+D_{t+1})/P_t\\)。取对数、在稳态附近线性化，迭代并加横截（泡沫项趋于零），得到 Campbell–Shiller 近似：</p> \\[d_t-p_t \\approx \\mathrm{const}+\\mathrm{E}_t\\sum_{j=0}^\\infty\\rho^j\\bigl(-\\Delta d_{t+1+j}+r_{t+1+j}\\bigr). \\]<p>股利–价格比高，对应预期股利增长低，或预期回报高。Lucas 树里两样都可以随 \\(y\\) 变；会计不挑哪一样为主。缺口是把「价格相对股利」从均衡函数翻译成可操作的预期之和，以便下一课谈可预测性、再下一课谈过度波动。</p><p><span class="marginnote">Campbell and Shiller, <em>RFS</em> 1(3), 1988。\\(\\rho\\) 是稳态 \\(P/(P+D)\\) 附近的线性化常数，接近 1。近似误差在波动不大时是二阶。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>会计步骤：定义、取对数、线性化、向前迭代、用横截丢掉 \\(p_{t+\\infty}\\)。没有用到无套利以外的东西——甚至无套利也不必需，只要回报按这个定义记账。SDF 进入的是：\\(\\mathrm{E}_t r_{t+1}\\) 由 \\(\\mathrm{E}_t[m_{t+1}(1+R_{t+1})]=1\\) 约束，于是「预期回报」不是自由的。本课先把恒等式钉住，欧拉下一课再请回来谈可预测性意味着什么。</p>',10)),(e(),p(c,null,{default:t(()=>[d(r,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEF%5B%221%2BR%20%3D%20(P'%2BD')%2FP%22%5D%20--%3E%20LIN%5B%22%E5%AF%B9%E6%95%B0%E7%BA%BF%E6%80%A7%22%5D%0A%20%20LIN%20--%3E%20CS%5B%22d-p%20%3D%20%E9%A2%84%E6%9C%9F%20-%CE%94d%20%2B%20%E9%A2%84%E6%9C%9F%20r%22%5D%0A%20%20TC%5B%22%E6%A8%AA%E6%88%AA%3A%20%E6%97%A0%E7%88%86%E7%82%B8%E6%B3%A1%E6%B2%AB%22%5D%20--%3E%20CS%0A%20%20TREE%5B%22Lucas%3A%20p(y)%22%5D%20--%3E%20CS%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<p>理性泡沫课已经允许横截失败。本课默认横截成立，把分解读成基本面会计。泡沫若在，会多一项，过度波动课会再碰到。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是现值的对数版本。高价格相对股利，必须「有来处」：要么后面股利更快长上来（分子），要么后面折现更低（分母，即预期回报低）。交换经济里果实 Markov，\\(d-p\\) 是 \\(y\\) 的函数，分解必须被该函数的条件期望满足——这是对 \\(p(y)\\) 的检验式会计，不是新均衡。</p><p>与 <a href="/econ/stochastic-discount-factor">SDF</a> 的接法：把 \\(r\\) 换成风险调整后的意外，分解仍成立，只是「预期回报」含溢价。不要把分解写成 CAPM 的 beta 展开——那是对预期回报的特化，见 <a href="/econ/capm-theory">capm-theory</a>，本课不特化。</p><p><span class="marginnote">向量自回归把 \\(\\Delta d\\) 与 \\(r\\) 的预期写成可估计的线性投影。那是测量。本课只保留恒等式。投影是否等于理性条件期望，是联合假说。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在本课报告股利–价格比对回报的回归斜率。下一课现值恒等式与可预测性才问：若股利增长几乎不可预测，则 \\(d-p\\) 必须预测回报——这是会计推论，不是异象猎取。也不要把对数线性当成精确的无套利约束；精确版本用总额而非对数，Cogley–Sargent 等讨论过近似质量。</p><p>后课默认：在横截下，\\(d-p\\) 是预期股利增长与预期回报的折现差。Lucas 树的 \\(p(y)\\) 必须服从这套会计。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>对数线性现值：股利–价格比编码未来 \\(\\Delta d\\) 与 \\(r\\) 的预期。</li><li>是回报定义加横截，不是新的偏好。</li><li>泡沫项被横截关掉；行为课序另开那条缝。</li><li>出处：Campbell and Shiller, <em>RFS</em> 1988。</li></ul>',10))])}const D=i(m,[["render",h]]);export{A as __pageData,D as default};
